"""Build checks use generated bytes, never commercial ROM/runtime fixtures."""
import hashlib
import io
import json
from pathlib import Path
import tarfile
import zipfile

import pytest

from scripts import fetch_runtime as runtime
from scripts.check_public_source import violations


def fixture_cache(tmp_path):
    vendor = tmp_path / 'vendor'
    archive = vendor / 'runtime-downloads/demo_libretro.so.zip'
    archive.parent.mkdir(parents=True)
    binary = b'generated test-only runtime payload'
    with zipfile.ZipFile(archive, 'w') as output:
        output.writestr('demo_libretro.so', binary)
    entries = {'demo_libretro.so.zip': {
        'url': 'https://example.invalid/demo_libretro.so.zip',
        'sha256': runtime.digest(archive),
        'binary_sha256': hashlib.sha256(binary).hexdigest(),
    }}
    lock = tmp_path / 'runtime-lock.json'
    lock.write_text(json.dumps(entries))
    return vendor, archive, entries, lock


def test_offline_materialize_preserves_reviewed_lock(tmp_path, monkeypatch):
    vendor, archive, entries, lock = fixture_cache(tmp_path)
    original = lock.read_bytes()
    monkeypatch.setattr(runtime.subprocess, 'run', lambda *args, **kwargs: pytest.fail('offline path attempted network'))
    paths = dict([runtime.fetch_one(vendor, 'demo_libretro.so.zip', entries['demo_libretro.so.zip'], True)])
    runtime.materialize(paths, entries, vendor)
    assert (vendor / 'libretro/demo_libretro.so').read_bytes() == b'generated test-only runtime payload'
    assert lock.read_bytes() == original
    archive.write_bytes(b'mutable upstream changed')
    with pytest.raises(ValueError, match='SHA256 mismatch'):
        runtime.fetch_one(vendor, 'demo_libretro.so.zip', entries['demo_libretro.so.zip'], False)
    assert lock.read_bytes() == original


def test_offline_missing_never_fetches(tmp_path, monkeypatch):
    vendor, archive, entries, _ = fixture_cache(tmp_path)
    archive.unlink()
    monkeypatch.setattr(runtime.subprocess, 'run', lambda *args, **kwargs: pytest.fail('offline path attempted network'))
    with pytest.raises(ValueError, match='incomplete'):
        runtime.fetch_one(vendor, 'demo_libretro.so.zip', entries['demo_libretro.so.zip'], True)


def test_private_backup_restores_only_locked_files(tmp_path):
    vendor, archive, entries, lock = fixture_cache(tmp_path)
    (vendor / 'secret-save.sav').write_bytes(b'private user data')
    bundle = tmp_path / 'private-cache.tar.gz'
    runtime.create_bundle(bundle, lock, entries, vendor)
    with tarfile.open(bundle) as contents:
        assert set(contents.getnames()) == {'runtime-lock.json', 'archives/demo_libretro.so.zip'}
    fresh = tmp_path / 'fresh-vendor'
    runtime.restore_bundle(bundle, lock, entries, fresh)
    assert runtime.digest(fresh / 'runtime-downloads/demo_libretro.so.zip') == runtime.digest(archive)
    assert not (fresh / 'secret-save.sav').exists()
    other = tmp_path / 'other-lock.json'; other.write_text('{}')
    with pytest.raises(ValueError, match='another reviewed lock'):
        runtime.restore_bundle(bundle, other, entries, fresh)


def test_private_backup_rejects_extra_and_symlink_entries(tmp_path):
    vendor, _, entries, lock = fixture_cache(tmp_path)
    bundle = tmp_path / 'bad.tar.gz'
    with tarfile.open(bundle, 'w:gz') as output:
        item = tarfile.TarInfo('../../escape'); item.size = 1
        output.addfile(item, io.BytesIO(b'x'))
    with pytest.raises(ValueError, match='Unexpected'):
        runtime.restore_bundle(bundle, lock, entries, vendor)
    with tarfile.open(bundle, 'w:gz') as output:
        item = tarfile.TarInfo('runtime-lock.json'); item.type = tarfile.SYMTYPE; item.linkname = '/etc/passwd'
        output.addfile(item)
        item = tarfile.TarInfo('archives/demo_libretro.so.zip'); item.size = 0; output.addfile(item, io.BytesIO())
    with pytest.raises(ValueError, match='Unsafe'):
        runtime.restore_bundle(bundle, lock, entries, vendor)


