def test_extract_rejects_symlink_parent_and_oversize(tmp_path, monkeypatch):
    archive = tmp_path / 'asset.zip'
    with zipfile.ZipFile(archive, 'w') as output: output.writestr('folder/data', b'12345')
    root = tmp_path / 'root'; root.mkdir()
    outside = tmp_path / 'outside'; outside.mkdir()
    (root / 'folder').symlink_to(outside, target_is_directory=True)
    with pytest.raises(ValueError, match='symlink'):
        runtime.extract_zip(archive, root)
    assert not list(outside.iterdir())
    monkeypatch.setattr(runtime, 'MAX_ASSET_BYTES', 4)
    with pytest.raises(ValueError, match='Oversized'):
        runtime.extract_zip(archive, tmp_path / 'safe')


def test_lock_rejects_unreviewed_hash_and_url(tmp_path):
    _, _, entries, _ = fixture_cache(tmp_path)
    assert len(runtime.records(entries)) == 1
    entries['demo_libretro.so.zip']['url'] = 'http://example.invalid/core.zip'
    with pytest.raises(ValueError, match='HTTPS'): runtime.records(entries)
    entries['demo_libretro.so.zip']['url'] = 'https://example.invalid/core.zip'
    entries['demo_libretro.so.zip']['sha256'] = 'replace with latest'
    with pytest.raises(ValueError, match='SHA256'): runtime.records(entries)


