def test_screenshot_manifest_matches_exact_reviewed_bytes(tmp_path):
    folder = tmp_path / 'docs/screenshots'; folder.mkdir(parents=True)
    image = folder / 'library.png'; image.write_bytes(b'\x89PNG\0generated fixture pixels')
    manifest = {'source': 'self-rendered fixtures', 'files': [{'path': 'library.png', 'sha256': hashlib.sha256(image.read_bytes()).hexdigest()}]}
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    assert not violations(['docs/screenshots/library.png'], tmp_path)
    image.write_bytes(b'\x89PNG\0different unreviewed pixels')
    errors = violations(['docs/screenshots/library.png'], tmp_path)
    assert any('SHA256 mismatch' in reason for _, reason in errors)


def test_product_icons_require_own_mark_and_exact_reviewed_bytes(tmp_path):
    folder = tmp_path / 'web/icons'
    folder.mkdir(parents=True)
    source = tmp_path / 'web/favicon.svg'
    source.write_text('<svg xmlns="http://www.w3.org/2000/svg"/>')
    icon = folder / 'icon-192.png'
    icon.write_bytes(b'\x89PNG\0generated application mark')
    manifest = {'source': 'web/favicon.svg', 'source_sha256': hashlib.sha256(source.read_bytes()).hexdigest(),
                'files': [{'path': icon.name, 'sha256': hashlib.sha256(icon.read_bytes()).hexdigest()}]}
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    assert not violations(['web/icons/icon-192.png'], tmp_path)
    # A replacement of either the reviewed vector or rendered icon must fail.
    icon.write_bytes(b'\x89PNG\0unreviewed artwork')
    assert violations(['web/icons/icon-192.png'], tmp_path)
    manifest['files'][0]['sha256'] = hashlib.sha256(icon.read_bytes()).hexdigest()
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    source.write_text('<svg>different mark</svg>')
    assert violations(['web/icons/icon-192.png'], tmp_path)
    # This manifest is not an escape hatch for unrelated cover caches.
    manifest['source_sha256'] = hashlib.sha256(source.read_bytes()).hexdigest()
    manifest['files'][0]['path'] = 'cover.png'
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    assert violations(['web/icons/cover.png'], tmp_path)


@pytest.mark.parametrize('old_tag', [
    '',
    '<script src="./retroone-input.js"></script>',
    '<script src="./retroone-input.js?v=older-release"></script>',
])
def test_stream_boot_versions_bridge_once_and_preserves_upstream_assets(tmp_path, old_tag):
    init = Path(__file__).resolve().parents[1] / 'container/root/custom-cont-init.d/99-retroone'
    code = init.read_text().split("python3 - <<'PY'\n", 1)[1].rsplit('\nPY', 1)[0]
    page = tmp_path / 'index.html'
    bridge = tmp_path / 'retroone-input.js'
    upstream = '<script type="module" src="./assets/selkies-original.js"></script>'
    page.write_text('<html><head>'+old_tag+upstream+'</head><body></body></html>')
    bridge.write_text('// generated bridge version one')
    code = code.replace("Path('/usr/share/selkies/web/index.html')", f'Path({str(page)!r})')
    exec(compile(code, str(init), 'exec'), {})
    first = page.read_text()
    assert first.count('retroone-input.js') == 1
    assert upstream in first
    assert '?v='+hashlib.sha256(bridge.read_bytes()).hexdigest()[:16] in first
    exec(compile(code, str(init), 'exec'), {})
    assert page.read_text() == first
    bridge.write_text('// generated bridge version two')
    exec(compile(code, str(init), 'exec'), {})
    assert page.read_text() != first
    assert page.read_text().count('retroone-input.js') == 1
    assert upstream in page.read_text()


from scripts import browser_runtime_assets as browser


def browser_fixture(tmp_path):
    source = tmp_path / 'source-data'; source.mkdir()
    contents = {'loader.js': b'generated loader fixture', 'emulator.min.js': b'generated framework fixture',
                'version.json': b'{"version":"fixture"}', 'cores/generated.data': b'generated core test bytes'}
    files = []
    for name, payload in contents.items():
        target = source / name; target.parent.mkdir(parents=True, exist_ok=True); target.write_bytes(payload)
        files.append({'path': name, 'url': 'https://cdn.emulatorjs.org/4.3.0-pre/data/' + name,
                      'size': len(payload), 'sha256': hashlib.sha256(payload).hexdigest()})
    document = {'schema_version': 1, 'version': '4.3.0-pre',
                'source': 'https://cdn.emulatorjs.org/4.3.0-pre/data/', 'files': files}
    lock = tmp_path / 'browser-lock.json'; lock.write_text(json.dumps(document))
    return source, lock, document


def test_browser_full_tree_activation_preserves_old_runtime_and_lock(tmp_path, monkeypatch):
    source, lock, document = browser_fixture(tmp_path); original = lock.read_bytes()
    vendor = tmp_path / 'vendor'; old = vendor / 'emulatorjs/data'; old.mkdir(parents=True)
    (old / 'old-only.js').write_text('preserve this older runtime')
    (source / 'unreviewed-private.txt').write_text('do not include')
    monkeypatch.setattr(browser.subprocess, 'run', lambda *args, **kwargs: pytest.fail('offline attempted network'))
    paths = browser.prepare_cache(vendor, original, offline=True, source=source)
    result = browser.materialize(vendor, original, paths)
    assert result['changed'] is True
    assert (Path(result['backup']) / 'data/old-only.js').read_text() == 'preserve this older runtime'
    assert not (old / 'old-only.js').exists() and not (old / 'unreviewed-private.txt').exists()
    marker = json.loads((old / '.retroone-runtime.json').read_text())
    assert marker == {'version': '4.3.0-pre', 'lock_sha256': hashlib.sha256(original).hexdigest()}
    browser.verify_tree(old, document['files'], original)
    assert browser.materialize(vendor, original, paths) == {'changed': False, 'backup': None}
    assert lock.read_bytes() == original


def test_browser_verify_only_can_check_source_without_writes_or_network(tmp_path, monkeypatch):
    source, lock, _ = browser_fixture(tmp_path); vendor = tmp_path / 'never-created'
